const anchor = (
  id: string,
  entityType: CognitiveBenchmarkEvidenceAnchor['entityType'],
  entityId: string,
  excerpt: string,
  attribution: Exclude<EpistemicAttribution, 'mixed' | 'not_applicable'>,
  effectiveAt: string,
  current = true,
  options: Partial<CognitiveBenchmarkEvidenceAnchor> = {},
): CognitiveBenchmarkEvidenceAnchor => ({
  id,
  entityType,
  entityId,
  revisionId: `${entityId}-r1`,
  location: {
    kind: 'text',
    fieldPath: entityType === 'source' ? 'description' : entityType === 'thinking_event' ? 'summary' : 'text',
    blockId: `${id}-block-1`,
    startOffset: 0,
    endOffset: excerpt.length,
  },
  excerpt,
  speaker: attribution === 'source_author' ? 'Fixture source author' : 'Fixture user',
  authorship: attribution === 'source_author' ? 'source_author' : 'user',
  authority: current ? 'canonical' : 'superseded',
  temporalStatus: current ? 'current' : 'historical',
  contentHash: `fixture:${id}:sha256-v1`,
  effectiveAt,
  recordedAt: effectiveAt,
  current,
  privacyPolicy: 'external_ai_allowed',
  invalidationState: 'valid',
  ...options,
});

