function benchmarkCase(
  id: string,
  queryClass: CognitiveBenchmarkCase['queryClass'],
  query: string,
  requiredEvidenceAnchorIds: string[],
  expectedAttribution: EpistemicAttribution,
  options: Partial<CognitiveBenchmarkCase> = {},
): CognitiveBenchmarkCase {
  const abstentionRequired = options.abstentionRequired || false;
  return {
    id,
    queryClass,
    query,
    requiredEvidenceAnchorIds,
    acceptableOptionalEvidenceAnchorIds: options.acceptableOptionalEvidenceAnchorIds || [],
    expectedAttribution,
    expectedAnswerClaims: options.expectedAnswerClaims || (abstentionRequired ? [] : [{
      id: `${id}-claim-1`,
      statementBoundary: 'State only the narrow conclusion supported by the required evidence.',
      requiredCitationGroups: requiredEvidenceAnchorIds.length ? [requiredEvidenceAnchorIds] : [],
      contraryEvidenceAnchorIds: options.contraryEvidenceAnchorIds || [],
    }]),
    contraryEvidenceAnchorIds: options.contraryEvidenceAnchorIds || [],
    mustExcludeEvidenceAnchorIds: options.mustExcludeEvidenceAnchorIds || [],
    expectedCanonicalRelationIds: options.expectedCanonicalRelationIds || [],
    acceptableCandidateRelationIds: options.acceptableCandidateRelationIds || [],
    mustExcludeRelationIds: options.mustExcludeRelationIds || [],
    forbiddenConclusions: options.forbiddenConclusions || ['Do not attribute unsupported beliefs to the user.'],
    acceptableAnswerBoundaries: options.acceptableAnswerBoundaries || ['Answer only from the listed evidence and state material uncertainty.'],
    abstentionRequired,
    securityScenario: options.securityScenario,
    retrievalCompleteness: options.retrievalCompleteness,
    budget: options.budget || {
      maxEvidenceAnchors: queryClass === 'deterministic_analytics' ? 50 : 12,
      maxLatencyMs: queryClass === 'deterministic_analytics' || queryClass === 'exact_retrieval' ? 800 : 3_000,
      maxWeightedCostUnits: queryClass === 'exact_retrieval' || queryClass === 'deterministic_analytics' ? 0 : 1,
      generationAllowed: queryClass !== 'exact_retrieval' && queryClass !== 'deterministic_analytics',
    },
    notes: options.notes,
  };
}

